import java.util.ArrayList;

public class ListFlattenerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static ArrayList<Integer> inner(int... values) {
        ArrayList<Integer> list = new ArrayList<>();
        for (int v : values) {
            list.add(v);
        }
        return list;
    }

    public static void main(String[] args) {
        ArrayList<ArrayList<Integer>> nested = new ArrayList<>();
        nested.add(inner(1, 2));
        nested.add(inner(3));
        nested.add(inner());
        nested.add(inner(4, 5));
        try {
            check("mixed inner sizes", "[1, 2, 3, 4, 5]", String.valueOf(ListFlattener.flatten(nested)));
            check("outer list itself unchanged", 4, nested.size());

            ArrayList<ArrayList<Integer>> single = new ArrayList<>();
            single.add(inner(7, 8, 9));
            check("one inner list", "[7, 8, 9]", String.valueOf(ListFlattener.flatten(single)));

            ArrayList<ArrayList<Integer>> empties = new ArrayList<>();
            empties.add(inner());
            empties.add(inner());
            check("only empty inner lists", "[]", String.valueOf(ListFlattener.flatten(empties)));

            check("empty outer list", "[]", String.valueOf(ListFlattener.flatten(new ArrayList<>())));

            ArrayList<ArrayList<Integer>> dupes = new ArrayList<>();
            dupes.add(inner(2, 2));
            dupes.add(inner(2));
            check("duplicates are kept", "[2, 2, 2]", String.valueOf(ListFlattener.flatten(dupes)));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

