import java.util.ArrayList;

public class ListFlattener {

    public static ArrayList<Integer> flatten(ArrayList<ArrayList<Integer>> nested) {
        ArrayList<Integer> result = new ArrayList<>();
        for (ArrayList<Integer> innerList : nested) {
            for (int value : innerList) {
                result.add(value);
            }
        }
        return result;
    }
}
